import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.ArrayList;
import java.util.Objects;

/**
 * Core sorting contract for arrays and lists.
 * @param <T> element type
 */
interface SortingAlgorithm<T> {
    void sort(T[] arr);
    void sort(List<T> list);
}

/**
 * Sorting operations with metrics and statistics tracking.
 * @param <T> element type
 */
interface SortOperations<T> extends SortingAlgorithm<T> {
    SortStatistics getStatistics();
    void resetStatistics();
}

/**
 * Immutable statistics snapshot for a sort operation.
 * Tracks comparisons, swaps, and derived metrics.
 */
final class SortStatistics {
    private final long comparisons;
    private final long swaps;

    SortStatistics(long comparisons, long swaps) {
        this.comparisons = comparisons;
        this.swaps = swaps;
    }

    public long getComparisons() {
        return comparisons;
    }

    public long getSwaps() {
        return swaps;
    }

    public double getComparisonsPerSwap() {
        return swaps == 0 ? Double.POSITIVE_INFINITY : (double) comparisons / swaps;
    }

    public long getTotalOperations() {
        return comparisons + swaps;
    }

    @Override
    public String toString() {
        return String.format("Comparisons: %d, Swaps: %d, Total: %d", comparisons, swaps, getTotalOperations());
    }

    @Override
    public boolean equals(Object obj) {
        if (!(obj instanceof SortStatistics)) return false;
        SortStatistics other = (SortStatistics) obj;
        return comparisons == other.comparisons && swaps == other.swaps;
    }

    @Override
    public int hashCode() {
        return Objects.hash(comparisons, swaps);
    }
}

/**
 * Records sorting operation metrics (comparisons and swaps).
 * Can be enabled/disabled for performance control.
 */
interface MetricsRecorder {
    void recordComparison();
    void recordSwap();
    SortStatistics snapshot();
    void reset();
}

class MetricsCollector implements MetricsRecorder {
    private final boolean enabled;
    private long comparisons;
    private long swaps;

    MetricsCollector(boolean enabled) {
        this.enabled = enabled;
    }

    @Override
    public void recordComparison() {
        if (enabled) comparisons++;
    }

    @Override
    public void recordSwap() {
        if (enabled) swaps++;
    }

    @Override
    public SortStatistics snapshot() {
        return new SortStatistics(comparisons, swaps);
    }

    @Override
    public void reset() {
        comparisons = 0;
        swaps = 0;
    }
}

class DisabledMetricsRecorder implements MetricsRecorder {
    @Override
    public void recordComparison() {}

    @Override
    public void recordSwap() {}

    @Override
    public SortStatistics snapshot() {
        return new SortStatistics(0, 0);
    }

    @Override
    public void reset() {}
}

class MetricsFactory {
    private static final MetricsRecorder DISABLED = new DisabledMetricsRecorder();

    static MetricsRecorder createCollector(boolean trackMetrics) {
        return trackMetrics ? new MetricsCollector(true) : DISABLED;
    }

    static MetricsRecorder createDisabled() {
        return DISABLED;
    }

    static MetricsRecorder createEnabled() {
        return new MetricsCollector(true);
    }
}

/**
 * Abstraction for accessing and modifying collections (arrays/lists).
 * Enables decoupled sorting algorithms from data structure details.
 * @param <T> element type
 */
interface DataAccessor<T> {
    int size();
    T get(int index);
    void set(int index, T value);
    void swap(int i, int j);

    /**
     * Calculates pass limit for bubble sort optimization.
     */
    default int getPassLimit(int passIndex) {
        return size() - passIndex - 1;
    }
}

class CompositeAccessor<T> implements DataAccessor<T> {
    private final DataAccessor<T> delegate;
    private final MetricsRecorder metrics;

    CompositeAccessor(DataAccessor<T> delegate, MetricsRecorder metrics) {
        this.delegate = delegate;
        this.metrics = metrics;
    }

    @Override
    public int size() {
        return delegate.size();
    }

    @Override
    public T get(int index) {
        return delegate.get(index);
    }

    @Override
    public void set(int index, T value) {
        delegate.set(index, value);
    }

    @Override
    public void swap(int i, int j) {
        delegate.swap(i, j);
        metrics.recordSwap();
    }
}

class SwapUtility {
    static <T> void swap(DataAccessor<T> accessor, int i, int j) {
        T temp = accessor.get(i);
        accessor.set(i, accessor.get(j));
        accessor.set(j, temp);
    }
}

class ArrayAccessor<T> implements DataAccessor<T> {
    private final T[] arr;

    ArrayAccessor(T[] arr) {
        this.arr = arr;
    }

    @Override
    public int size() {
        return arr.length;
    }

    @Override
    public T get(int index) {
        return arr[index];
    }

    @Override
    public void set(int index, T value) {
        arr[index] = value;
    }

    @Override
    public void swap(int i, int j) {
        SwapUtility.swap(this, i, j);
    }
}

class ListAccessor<T> implements DataAccessor<T> {
    private final List<T> list;

    ListAccessor(List<T> list) {
        this.list = list;
    }

    @Override
    public int size() {
        return list.size();
    }

    @Override
    public T get(int index) {
        return list.get(index);
    }

    @Override
    public void set(int index, T value) {
        list.set(index, value);
    }

    @Override
    public void swap(int i, int j) {
        SwapUtility.swap(this, i, j);
    }
}

class InputValidator {
    static <T> T requireNonNull(T obj, String message) {
        if (obj == null) throw new IllegalArgumentException(message);
        return obj;
    }

    static void validateArray(Object[] arr) {
        requireNonNull(arr, "Array cannot be null");
    }

    static void validateListSize(List<?> list) {
        requireNonNull(list, "List cannot be null");
        if (list.size() < 2) {
            throw new IllegalArgumentException("List must have at least 2 elements");
        }
    }

    static boolean shouldSort(List<?> list) {
        return list != null && list.size() >= 2;
    }
}

class AccessorFactory {
    static <T> DataAccessor<T> createArrayAccessor(T[] arr) {
        return new ArrayAccessor<>(arr);
    }

    static <T> DataAccessor<T> createListAccessor(List<T> list) {
        return new ListAccessor<>(list);
    }

    static <T> DataAccessor<T> withMetrics(DataAccessor<T> accessor, MetricsRecorder metrics) {
        return new CompositeAccessor<>(accessor, metrics);
    }

    static <T> DataAccessor<T> create(T[] arr, MetricsRecorder metrics) {
        return withMetrics(createArrayAccessor(arr), metrics);
    }

    static <T> DataAccessor<T> create(List<T> list, MetricsRecorder metrics) {
        return withMetrics(createListAccessor(list), metrics);
    }
}

class MetricsAwareComparator<T> implements Comparator<T> {
    private final Comparator<T> delegate;
    private final MetricsRecorder metrics;

    MetricsAwareComparator(Comparator<T> delegate, MetricsRecorder metrics) {
        this.delegate = delegate;
        this.metrics = metrics;
    }

    boolean isGreater(T a, T b) {
        metrics.recordComparison();
        return delegate.compare(a, b) > 0;
    }

    @Override
    public int compare(T a, T b) {
        metrics.recordComparison();
        return delegate.compare(a, b);
    }
}

/**
 * Strategy for executing a single sorting pass.
 * Different algorithms implement pass logic differently.
 * @param <T> element type
 */
interface PassStrategy<T> {
    /**
     * Executes one pass of the sorting algorithm.
     * @return true if elements were swapped, false if array is sorted
     */
    boolean execute(DataAccessor<T> accessor, int passIndex);
}

class BubblePassStrategy<T> implements PassStrategy<T> {
    private final MetricsAwareComparator<T> comparator;

    BubblePassStrategy(MetricsAwareComparator<T> comparator) {
        this.comparator = comparator;
    }

    @Override
    public boolean execute(DataAccessor<T> accessor, int passIndex) {
        boolean swapped = false;
        int limit = accessor.getPassLimit(passIndex);
        for (int j = 0; j < limit; j++) {
            if (comparator.isGreater(accessor.get(j), accessor.get(j + 1))) {
                accessor.swap(j, j + 1);
                swapped = true;
            }
        }
        return swapped;
    }
}

/**
 * Orchestrates the overall sorting loop structure.
 * Different algorithms may have different termination and pass iteration logic.
 * @param <T> element type
 */
interface SortExecutor<T> {
    void execute(DataAccessor<T> accessor, PassStrategy<T> passStrategy);
}

/**
 * Bubble sort loop executor: iterates passes until no swaps occur.
 */
class BubbleSortExecutor<T> implements SortExecutor<T> {
    @Override
    public void execute(DataAccessor<T> accessor, PassStrategy<T> passStrategy) {
        int passes = accessor.size() - 1;
        for (int i = 0; i < passes; i++) {
            if (!passStrategy.execute(accessor, i)) break;
        }
    }
}

class StrategyFactory<T> {
    private final MetricsAwareComparator<T> comparator;

    StrategyFactory(MetricsAwareComparator<T> comparator) {
        this.comparator = comparator;
    }

    PassStrategy<T> createBubblePassStrategy() {
        return new BubblePassStrategy<>(comparator);
    }

    <A> SortExecutor<A> createBubbleSortExecutor() {
        return new BubbleSortExecutor<>();
    }
}

class SortContext<T> {
    private final DataAccessor<T> accessor;
    private final PassStrategy<T> passStrategy;
    private final SortExecutor<T> executor;

    SortContext(DataAccessor<T> accessor, PassStrategy<T> passStrategy, SortExecutor<T> executor) {
        this.accessor = accessor;
        this.passStrategy = passStrategy;
        this.executor = executor;
    }

    void execute() {
        executor.execute(accessor, passStrategy);
    }
}

final class SortConfiguration<T> {
    final Comparator<T> comparator;
    final MetricsRecorder metrics;

    SortConfiguration(Comparator<T> comparator, MetricsRecorder metrics) {
        this.comparator = comparator;
        this.metrics = metrics;
    }

    static <T> SortConfiguration<T> create(Comparator<T> comparator, boolean trackMetrics) {
        return new SortConfiguration<>(comparator, MetricsFactory.createCollector(trackMetrics));
    }

    static <T> SortConfiguration<T> createDefault(Comparator<T> comparator) {
        return create(comparator, true);
    }
}

/**
 * Abstract base for sorting algorithms.
 * Provides common infrastructure: configuration, metrics, strategy factories.
 * Subclasses define pass and executor strategies.
 * @param <T> element type
 */
abstract class BaseSorter<T> implements SortOperations<T> {
    protected final MetricsAwareComparator<T> comparator;
    protected final MetricsRecorder metrics;
    protected final StrategyFactory<T> strategyFactory;

    protected BaseSorter(SortConfiguration<T> config) {
        Objects.requireNonNull(config, "Configuration cannot be null");
        this.metrics = config.metrics;
        this.comparator = new MetricsAwareComparator<>(config.comparator, metrics);
        this.strategyFactory = new StrategyFactory<>(this.comparator);
    }

    @Override
    public SortStatistics getStatistics() {
        return metrics.snapshot();
    }

    @Override
    public void resetStatistics() {
        metrics.reset();
    }

    protected abstract PassStrategy<T> createPassStrategy();

    protected abstract <A> SortExecutor<A> createExecutor();

    protected void sortArray(T[] arr, DataAccessor<T> accessor) {
        InputValidator.validateArray(arr);
        executeSortContext(accessor);
    }

    protected void sortList(List<T> list, DataAccessor<T> accessor) {
        if (InputValidator.shouldSort(list)) {
            executeSortContext(accessor);
        }
    }

    protected void executeSortContext(DataAccessor<T> accessor) {
        PassStrategy<T> strategy = createPassStrategy();
        SortExecutor<T> executor = createExecutor();
        new SortContext<>(accessor, strategy, executor).execute();
    }
}

/**
 * Bubble sort implementation with configurable metrics and comparators.
 * Supports both arrays and lists. Early termination when sorted.
 * @param <T> element type, must be comparable via provided comparator
 */
class BubbleSort<T> extends BaseSorter<T> {
    private BubbleSort(SortConfiguration<T> config) {
        super(config);
    }

    @Override
    public void sort(T[] arr) {
        sortArray(arr, AccessorFactory.create(arr, metrics));
    }

    @Override
    public void sort(List<T> list) {
        sortList(list, AccessorFactory.create(list, metrics));
    }

    @Override
    protected PassStrategy<T> createPassStrategy() {
        return strategyFactory.createBubblePassStrategy();
    }

    @Override
    protected <A> SortExecutor<A> createExecutor() {
        return strategyFactory.createBubbleSortExecutor();
    }

    static class Builder<T> {
        private Comparator<T> comparator = Comparator.naturalOrder();
        private boolean trackMetrics = true;

        public Builder<T> withComparator(Comparator<T> comparator) {
            this.comparator = comparator;
